def list_directory(server_id=None, path=None, cursor=None, limit=None, include_files=None, include_directories=None, refresh_index=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, posixpath, random, string
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0059000" if __import__("os").path.isdir("./environment_mix/0059000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return f"{prefix}_" + "".join(random.choice(alphabet) for _ in range(20))

    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _norm_abs_path(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s:
            return None
        if not s.startswith("/"):
            return None
        n = posixpath.normpath(s)
        if not n.startswith("/"):
            n = "/" + n
        if n != "/" and n.endswith("/"):
            n = n.rstrip("/")
        return n

    def _resolve_under_root(root_abs, p):
        # Accept absolute or relative-to-root. If absolute doesn't share root prefix, treat as relative-to-root
        if not isinstance(p, str):
            return None, "path must be a string"
        pp = p.strip()
        if pp == "":
            return None, "path must be a non-empty string"

        if pp.startswith("/"):
            joined = posixpath.normpath(pp)
            if not joined.startswith("/"):
                joined = "/" + joined
            # Relaxation: if absolute path is outside root, interpret it as relative to root
            if root_abs != "/" and not (joined == root_abs or joined.startswith(root_abs + "/")):
                joined = posixpath.normpath(posixpath.join(root_abs, pp.lstrip("/")))
        else:
            joined = posixpath.normpath(posixpath.join(root_abs, pp))

        if not joined.startswith("/"):
            joined = "/" + joined

        if root_abs != "/":
            if not (joined == root_abs or joined.startswith(root_abs + "/")):
                return None, "target path resolves outside server root_path"
        return joined, None

    def _log_operation(ops, op):
        ops.append(op)
        _save("ftp_operations.json", ops)

    # Validate inputs (must not raise)
    if not isinstance(server_id, str) or not re.match(r"^ftp_srv_[0-9A-Z]{18,}$", server_id):
        # still record operation (best-effort) is impossible without server_id FK; return validation error
        return _err("VALIDATION_ERROR", "server_id must match ^ftp_srv_[0-9A-Z]{18,}$")

    if not isinstance(path, str) or not path.strip():
        return _err("VALIDATION_ERROR", "path must be a non-empty string")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")

    if include_files is None:
        include_files = True
    if include_directories is None:
        include_directories = True
    if not isinstance(include_files, bool) or not isinstance(include_directories, bool):
        return _err("VALIDATION_ERROR", "include_files/include_directories must be boolean")
    if not include_files and not include_directories:
        # valid but returns empty
        pass

    if refresh_index is None:
        refresh_index = False
    if not isinstance(refresh_index, bool):
        return _err("VALIDATION_ERROR", "refresh_index must be boolean")

    if sort_by is None:
        sort_by = "name"
    if sort_by not in ("name", "path", "size_bytes", "updated_at", "created_at"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: name, path, size_bytes, updated_at, created_at")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    servers = _load("ftp_servers.json")
    srv = next((s for s in servers if s.get("id") == server_id), None)
    if not srv or srv.get("status") == "deleted":
        # cannot create op row due FK? FK requires existing server_id. Since it doesn't exist, return NOT_FOUND.
        return _err("NOT_FOUND", "FTP server profile not found")

    root_abs = _norm_abs_path(srv.get("root_path"))
    if root_abs is None:
        return _err("VALIDATION_ERROR", "server root_path is invalid")

    target_path, perr = _resolve_under_root(root_abs, path)
    # Create operation row first (business rule)
    ops = _load("ftp_operations.json")
    op_id = _gen_id("ftp_opr")
    op = {
        "id": op_id,
        "server_id": server_id,
        "tool_name": "list-directory",
        "target_path": target_path if target_path else None,
        "directory_id": None,
        "file_id": None,
        "transfer_id": None,
        "request_metadata": {
            "path": path,
            "cursor": cursor,
            "limit": limit,
            "include_files": include_files,
            "include_directories": include_directories,
            "refresh_index": refresh_index,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
        "result_metadata": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_z(),
        "updated_at": _now_z(),
    }
    if perr:
        op["status"] = "failed"
        op["error_code"] = "INVALID_PATH"
        op["error_message"] = perr
        op["finished_at"] = _now_z()
        op["updated_at"] = op["finished_at"]
        _log_operation(ops, op)
        return _err("VALIDATION_ERROR", perr)

    op["status"] = "running"
    op["started_at"] = _now_z()
    op["updated_at"] = op["started_at"]
    _log_operation(ops, op)

    # Quota/rate limit: enforce simple per-server recent rate based on existing operations:
    # max 60 operations/minute per server; else RATE_LIMIT
    ops = _load("ftp_operations.json")
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    recent = 0
    for r in ops:
        if r.get("server_id") != server_id:
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts and (now - ts).total_seconds() <= 60:
            recent += 1
    if recent > 60:
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["error_code"] = "RATE_LIMITED"
                r["error_message"] = "429 too many requests: rate limit exceeded"
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return _err("RATE_LIMIT", "rate limit exceeded")

    dirs = _load("ftp_directories.json")
    files = _load("ftp_files.json")

    # Ensure directory record exists for target_path (upsert)
    nowz = _now_z()
    dir_row = next((d for d in dirs if d.get("server_id") == server_id and d.get("path") == target_path), None)
    if dir_row is None:
        # parent directory resolution best-effort
        parent_path = posixpath.dirname(target_path.rstrip("/")) if target_path != "/" else None
        parent_id = None
        if parent_path and parent_path.startswith("/") and parent_path != target_path:
            parent_row = next((d for d in dirs if d.get("server_id") == server_id and d.get("path") == parent_path), None)
            if parent_row:
                parent_id = parent_row.get("id")
        dir_row = {
            "id": _gen_id("ftp_dir"),
            "server_id": server_id,
            "parent_directory_id": parent_id,
            "path": target_path,
            "name": posixpath.basename(target_path) if target_path != "/" else "/",
            "status": "present",
            "last_listed_at": nowz if refresh_index else None,
            "created_at": nowz,
            "updated_at": nowz,
        }
        dirs.append(dir_row)
    else:
        # refresh index = update last_listed_at
        if refresh_index:
            dir_row["last_listed_at"] = nowz
        dir_row["updated_at"] = nowz

    # Update operation with resolved directory_id
    for r in ops:
        if r.get("id") == op_id:
            r["directory_id"] = dir_row.get("id")
            r["updated_at"] = _now_z()
            break

    # "refresh_index" cannot truly query FTP offline; simulate by marking existing children as seen now (no new fabricated rows)
    # If refresh_index is true, mark all direct children under this directory path as updated/seen.
    if refresh_index:
        prefix = target_path.rstrip("/")
        if prefix == "":
            prefix = "/"
        if prefix != "/":
            prefix = prefix + "/"
        else:
            prefix = "/"

        for d in dirs:
            if d.get("server_id") == server_id and isinstance(d.get("path"), str) and d.get("path").startswith(prefix):
                # direct child only: exactly one segment beyond
                rel = d["path"][len(prefix):]
                if rel and "/" not in rel.strip("/"):
                    d["last_listed_at"] = nowz
                    d["updated_at"] = nowz
        for f in files:
            if f.get("server_id") == server_id and isinstance(f.get("path"), str) and f.get("path").startswith(prefix):
                rel = f["path"][len(prefix):]
                if rel and "/" not in rel.strip("/"):
                    f["last_seen_at"] = nowz
                    f["updated_at"] = nowz

    # Collect direct children entries
    entries = []
    prefix = target_path.rstrip("/")
    prefix = "/" if prefix == "" else prefix
    if prefix != "/":
        prefix = prefix + "/"
    else:
        prefix = "/"

    if include_directories:
        for d in dirs:
            if d.get("server_id") != server_id:
                continue
            p = d.get("path")
            if not isinstance(p, str) or not p.startswith(prefix):
                continue
            rel = p[len(prefix):]
            if not rel or "/" in rel.strip("/"):
                continue
            entries.append({"type": "directory", "directory": d})

    if include_files:
        for f in files:
            if f.get("server_id") != server_id:
                continue
            p = f.get("path")
            if not isinstance(p, str) or not p.startswith(prefix):
                continue
            rel = p[len(prefix):]
            if not rel or "/" in rel.strip("/"):
                continue
            entries.append({"type": "file", "file": f})

    # Safety limit
    if len(entries) > 100000:
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["error_code"] = "LIMIT_EXCEEDED"
                r["error_message"] = "list-directory result entries count exceeds 100000"
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return _err("VALIDATION_ERROR", "LIMIT_EXCEEDED", error_code="LIMIT_EXCEEDED")

    # Sort
    def _key(e):
        obj = e.get("directory") if e["type"] == "directory" else e.get("file")
        v = obj.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort_by == "size_bytes":
            return -1 if v is None else v
        return "" if v is None else str(v).lower()

    rev = (sort_order == "desc")
    entries.sort(key=_key, reverse=rev)

    # Pagination: cursor is an opaque "offset:<n>"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        m = re.match(r"^offset:(\d+)$", cursor.strip())
        if not m:
            return _err("VALIDATION_ERROR", "invalid cursor")
        offset = int(m.group(1))

    page = entries[offset: offset + limit]
    next_cursor = None
    if offset + limit < len(entries):
        next_cursor = f"offset:{offset + limit}"

    # Persist index updates and operation success
    _save("ftp_directories.json", dirs)
    _save("ftp_files.json", files)

    result_meta = {"entries_count": len(page), "total_entries": len(entries)}
    for r in ops:
        if r.get("id") == op_id:
            r["status"] = "succeeded"
            r["result_metadata"] = result_meta
            r["finished_at"] = _now_z()
            r["updated_at"] = r["finished_at"]
            break
    _save("ftp_operations.json", ops)

    return {
        "operation": next((r for r in ops if r.get("id") == op_id), None),
        "server": srv,
        "directory": dir_row,
        "entries": page,
        "page_info": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": next_cursor is not None, "total": len(entries)},
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def delete_file(server_id=None, remote_path=None, file_id=None, force=None, **_extra):
    import json, os, datetime, time, re, posixpath, random, string
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0059000" if __import__("os").path.isdir("./environment_mix/0059000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return f"{prefix}_" + "".join(random.choice(alphabet) for _ in range(20))

    def _norm_abs_path(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s or not s.startswith("/"):
            return None
        n = posixpath.normpath(s)
        if not n.startswith("/"):
            n = "/" + n
        if n != "/" and n.endswith("/"):
            n = n.rstrip("/")
        return n

    def _resolve_under_root(root_abs, p):
        if p is None:
            return None, None
        if not isinstance(p, str):
            return None, "remote_path must be a string"
        pp = p.strip()
        if pp == "":
            return None, "remote_path must be a non-empty string"

        if pp.startswith("/"):
            joined = posixpath.normpath(pp)
            if not joined.startswith("/"):
                joined = "/" + joined
            # Relaxation: if absolute is outside root, treat as relative to root
            if root_abs != "/" and not (joined == root_abs or joined.startswith(root_abs + "/")):
                joined = posixpath.normpath(posixpath.join(root_abs, pp.lstrip("/")))
        else:
            joined = posixpath.normpath(posixpath.join(root_abs, pp))
        if not joined.startswith("/"):
            joined = "/" + joined

        if root_abs != "/":
            if not (joined == root_abs or joined.startswith(root_abs + "/")):
                return None, "target path resolves outside server root_path"
        return joined, None

    # Validate
    if not isinstance(server_id, str) or not re.match(r"^ftp_srv_[0-9A-Z]{18,}$", server_id):
        return _err("VALIDATION_ERROR", "server_id must match ^ftp_srv_[0-9A-Z]{18,}$")
    if force is None:
        force = False
    if not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be boolean")
    if remote_path is None and file_id is None:
        return _err("VALIDATION_ERROR", "either remote_path or file_id must be provided")
    if file_id is not None and (not isinstance(file_id, str) or not re.match(r"^ftp_fil_[0-9A-Z]{18,}$", file_id)):
        return _err("VALIDATION_ERROR", "file_id must match ^ftp_fil_[0-9A-Z]{18,}$")

    servers = _load("ftp_servers.json")
    srv = next((s for s in servers if s.get("id") == server_id), None)
    if not srv or srv.get("status") == "deleted":
        return _err("NOT_FOUND", "FTP server profile not found")

    # server disabled forbids delete-file
    if srv.get("status") == "disabled":
        ops = _load("ftp_operations.json")
        op = {
            "id": _gen_id("ftp_opr"),
            "server_id": server_id,
            "tool_name": "delete-file",
            "target_path": remote_path if isinstance(remote_path, str) else None,
            "directory_id": None,
            "file_id": file_id,
            "transfer_id": None,
            "request_metadata": {"remote_path": remote_path, "file_id": file_id, "force": force},
            "result_metadata": None,
            "status": "failed",
            "error_code": "SERVER_DISABLED",
            "error_message": "server profile is disabled",
            "started_at": _now_z(),
            "finished_at": _now_z(),
            "created_at": _now_z(),
            "updated_at": _now_z(),
        }
        ops.append(op)
        _save("ftp_operations.json", ops)
        return _err("INVALID_TRANSITION", "SERVER_DISABLED", error_code="SERVER_DISABLED")

    root_abs = _norm_abs_path(srv.get("root_path"))
    if root_abs is None:
        return _err("VALIDATION_ERROR", "server root_path is invalid")

    files = _load("ftp_files.json")
    ops = _load("ftp_operations.json")

    file_row = None
    target_path = None
    if file_id is not None:
        file_row = next((f for f in files if f.get("id") == file_id), None)
        if not file_row or file_row.get("server_id") != server_id:
            op = {
                "id": _gen_id("ftp_opr"),
                "server_id": server_id,
                "tool_name": "delete-file",
                "target_path": None,
                "directory_id": None,
                "file_id": file_id,
                "transfer_id": None,
                "request_metadata": {"remote_path": remote_path, "file_id": file_id, "force": force},
                "result_metadata": None,
                "status": "failed",
                "error_code": "NOT_FOUND",
                "error_message": "file not found",
                "started_at": _now_z(),
                "finished_at": _now_z(),
                "created_at": _now_z(),
                "updated_at": _now_z(),
            }
            ops.append(op)
            _save("ftp_operations.json", ops)
            return _err("NOT_FOUND", "target file not found")
        target_path = file_row.get("path")
    else:
        target_path, perr = _resolve_under_root(root_abs, remote_path)
        op = {
            "id": _gen_id("ftp_opr"),
            "server_id": server_id,
            "tool_name": "delete-file",
            "target_path": target_path if target_path else None,
            "directory_id": None,
            "file_id": None,
            "transfer_id": None,
            "request_metadata": {"remote_path": remote_path, "file_id": file_id, "force": force},
            "result_metadata": None,
            "status": "received",
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": _now_z(),
            "updated_at": _now_z(),
        }
        if perr:
            op["status"] = "failed"
            op["error_code"] = "INVALID_PATH"
            op["error_message"] = perr
            op["started_at"] = _now_z()
            op["finished_at"] = _now_z()
            op["updated_at"] = op["finished_at"]
            ops.append(op)
            _save("ftp_operations.json", ops)
            return _err("VALIDATION_ERROR", perr)
        ops.append(op)
        _save("ftp_operations.json", ops)
        file_row = next((f for f in files if f.get("server_id") == server_id and f.get("path") == target_path), None)

    # If file_id branch, create operation now with resolved target_path
    if file_id is not None:
        tp, perr = _resolve_under_root(root_abs, target_path if isinstance(target_path, str) else "")
        op = {
            "id": _gen_id("ftp_opr"),
            "server_id": server_id,
            "tool_name": "delete-file",
            "target_path": tp if tp else None,
            "directory_id": None,
            "file_id": file_id,
            "transfer_id": None,
            "request_metadata": {"remote_path": remote_path, "file_id": file_id, "force": force},
            "result_metadata": None,
            "status": "received",
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": _now_z(),
            "updated_at": _now_z(),
        }
        if perr:
            op["status"] = "failed"
            op["error_code"] = "INVALID_PATH"
            op["error_message"] = perr
            op["started_at"] = _now_z()
            op["finished_at"] = _now_z()
            op["updated_at"] = op["finished_at"]
            ops.append(op)
            _save("ftp_operations.json", ops)
            return _err("VALIDATION_ERROR", perr)
        ops.append(op)
        _save("ftp_operations.json", ops)

    op_id = ops[-1]["id"]
    # running
    for r in ops:
        if r.get("id") == op_id:
            r["status"] = "running"
            r["started_at"] = _now_z()
            r["updated_at"] = r["started_at"]
            r["file_id"] = file_row.get("id") if file_row else r.get("file_id")
            break
    _save("ftp_operations.json", ops)

    # Idempotency: if no file_row found by path, treat remote not-found as success, but record error_code NOT_FOUND
    if file_row is None:
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "succeeded"
                r["error_code"] = "NOT_FOUND"
                r["error_message"] = "remote reported file not found; marked deleted for idempotency"
                r["result_metadata"] = {"deleted": True, "idempotent": True}
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return {
            "operation": next((r for r in ops if r.get("id") == op_id), None),
            "file": None,
            "latency_ms": int((time.time() - _t0) * 1000),
        }

    # Lifecycle transitions: present -> deleting -> deleted (uploading cannot delete unless force)
    status0 = file_row.get("status")
    allowed = {
        "present": ["deleting", "deleted"],
        "uploading": ["present", "deleted"],
        "deleting": ["deleted"],
        "deleted": [],
    }
    if status0 == "uploading" and not force:
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["error_code"] = "CONFLICT"
                r["error_message"] = "file is uploading; use force to delete"
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return _err("CONFLICT", "file is uploading; use force to delete")

    # transition to deleting if possible
    if "deleting" in allowed.get(status0, []) and status0 != "deleting":
        file_row["status"] = "deleting"
        file_row["updated_at"] = _now_z()

    # Offline: treat remote deletion success; set deleted
    if "deleted" not in allowed.get(file_row.get("status"), []):
        # if currently deleting, it's allowed to go to deleted; if not, invalid
        if file_row.get("status") != "deleting" and file_row.get("status") != "present":
            for r in ops:
                if r.get("id") == op_id:
                    r["status"] = "failed"
                    r["error_code"] = "INVALID_TRANSITION"
                    r["error_message"] = f"cannot delete-file from status {status0}"
                    r["finished_at"] = _now_z()
                    r["updated_at"] = r["finished_at"]
                    break
            _save("ftp_operations.json", ops)
            return _err("INVALID_TRANSITION", f"cannot delete-file from status {status0}")
    file_row["status"] = "deleted"
    file_row["updated_at"] = _now_z()

    _save("ftp_files.json", files)

    for r in ops:
        if r.get("id") == op_id:
            r["status"] = "succeeded"
            r["result_metadata"] = {"deleted": True}
            r["finished_at"] = _now_z()
            r["updated_at"] = r["finished_at"]
            break
    _save("ftp_operations.json", ops)

    return {
        "operation": next((r for r in ops if r.get("id") == op_id), None),
        "file": file_row,
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def delete_directory(server_id=None, path=None, directory_id=None, recursive=None, force=None, **_extra):
    import json, os, datetime, time, re, posixpath, random, string
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0059000" if __import__("os").path.isdir("./environment_mix/0059000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return f"{prefix}_" + "".join(random.choice(alphabet) for _ in range(20))

    def _norm_abs_path(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s or not s.startswith("/"):
            return None
        n = posixpath.normpath(s)
        if not n.startswith("/"):
            n = "/" + n
        if n != "/" and n.endswith("/"):
            n = n.rstrip("/")
        return n

    def _resolve_under_root(root_abs, p):
        if p is None:
            return None, None
        if not isinstance(p, str):
            return None, "path must be a string"
        pp = p.strip()
        if pp == "":
            return None, "path must be a non-empty string"

        if pp.startswith("/"):
            joined = posixpath.normpath(pp)
            if not joined.startswith("/"):
                joined = "/" + joined
            # Relaxation: if absolute is outside root, treat as relative to root
            if root_abs != "/" and not (joined == root_abs or joined.startswith(root_abs + "/")):
                joined = posixpath.normpath(posixpath.join(root_abs, pp.lstrip("/")))
        else:
            joined = posixpath.normpath(posixpath.join(root_abs, pp))
        if not joined.startswith("/"):
            joined = "/" + joined

        if root_abs != "/":
            if not (joined == root_abs or joined.startswith(root_abs + "/")):
                return None, "target path resolves outside server root_path"
        return joined, None

    # Validate
    if not isinstance(server_id, str) or not re.match(r"^ftp_srv_[0-9A-Z]{18,}$", server_id):
        return _err("VALIDATION_ERROR", "server_id must match ^ftp_srv_[0-9A-Z]{18,}$")
    if recursive is None:
        recursive = False
    if force is None:
        force = False
    if not isinstance(recursive, bool) or not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "recursive/force must be boolean")
    if path is None and directory_id is None:
        return _err("VALIDATION_ERROR", "either path or directory_id must be provided")
    if directory_id is not None and (not isinstance(directory_id, str) or not re.match(r"^ftp_dir_[0-9A-Z]{18,}$", directory_id)):
        return _err("VALIDATION_ERROR", "directory_id must match ^ftp_dir_[0-9A-Z]{18,}$")

    servers = _load("ftp_servers.json")
    srv = next((s for s in servers if s.get("id") == server_id), None)
    if not srv or srv.get("status") == "deleted":
        return _err("NOT_FOUND", "FTP server profile not found")
    if srv.get("status") == "disabled":
        ops = _load("ftp_operations.json")
        op = {
            "id": _gen_id("ftp_opr"),
            "server_id": server_id,
            "tool_name": "delete-directory",
            "target_path": path if isinstance(path, str) else None,
            "directory_id": directory_id,
            "file_id": None,
            "transfer_id": None,
            "request_metadata": {"path": path, "directory_id": directory_id, "recursive": recursive, "force": force},
            "result_metadata": None,
            "status": "failed",
            "error_code": "SERVER_DISABLED",
            "error_message": "server profile is disabled",
            "started_at": _now_z(),
            "finished_at": _now_z(),
            "created_at": _now_z(),
            "updated_at": _now_z(),
        }
        ops.append(op)
        _save("ftp_operations.json", ops)
        return _err("INVALID_TRANSITION", "SERVER_DISABLED", error_code="SERVER_DISABLED")

    root_abs = _norm_abs_path(srv.get("root_path"))
    if root_abs is None:
        return _err("VALIDATION_ERROR", "server root_path is invalid")

    dirs = _load("ftp_directories.json")
    files = _load("ftp_files.json")
    ops = _load("ftp_operations.json")

    dir_row = None
    target_path = None

    if directory_id is not None:
        dir_row = next((d for d in dirs if d.get("id") == directory_id), None)
        if not dir_row or dir_row.get("server_id") != server_id:
            op = {
                "id": _gen_id("ftp_opr"),
                "server_id": server_id,
                "tool_name": "delete-directory",
                "target_path": None,
                "directory_id": directory_id,
                "file_id": None,
                "transfer_id": None,
                "request_metadata": {"path": path, "directory_id": directory_id, "recursive": recursive, "force": force},
                "result_metadata": None,
                "status": "failed",
                "error_code": "NOT_FOUND",
                "error_message": "directory not found",
                "started_at": _now_z(),
                "finished_at": _now_z(),
                "created_at": _now_z(),
                "updated_at": _now_z(),
            }
            ops.append(op)
            _save("ftp_operations.json", ops)
            return _err("NOT_FOUND", "target directory not found")
        target_path = dir_row.get("path")
    else:
        target_path, perr = _resolve_under_root(root_abs, path)
        op = {
            "id": _gen_id("ftp_opr"),
            "server_id": server_id,
            "tool_name": "delete-directory",
            "target_path": target_path if target_path else None,
            "directory_id": None,
            "file_id": None,
            "transfer_id": None,
            "request_metadata": {"path": path, "directory_id": directory_id, "recursive": recursive, "force": force},
            "result_metadata": None,
            "status": "received",
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": _now_z(),
            "updated_at": _now_z(),
        }
        if perr:
            op["status"] = "failed"
            op["error_code"] = "INVALID_PATH"
            op["error_message"] = perr
            op["started_at"] = _now_z()
            op["finished_at"] = _now_z()
            op["updated_at"] = op["finished_at"]
            ops.append(op)
            _save("ftp_operations.json", ops)
            return _err("VALIDATION_ERROR", perr)
        ops.append(op)
        _save("ftp_operations.json", ops)
        dir_row = next((d for d in dirs if d.get("server_id") == server_id and d.get("path") == target_path), None)

    # If directory_id branch, create operation now with resolved path
    if directory_id is not None:
        tp, perr = _resolve_under_root(root_abs, target_path if isinstance(target_path, str) else "")
        op = {
            "id": _gen_id("ftp_opr"),
            "server_id": server_id,
            "tool_name": "delete-directory",
            "target_path": tp if tp else None,
            "directory_id": directory_id,
            "file_id": None,
            "transfer_id": None,
            "request_metadata": {"path": path, "directory_id": directory_id, "recursive": recursive, "force": force},
            "result_metadata": None,
            "status": "received",
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": _now_z(),
            "updated_at": _now_z(),
        }
        if perr:
            op["status"] = "failed"
            op["error_code"] = "INVALID_PATH"
            op["error_message"] = perr
            op["started_at"] = _now_z()
            op["finished_at"] = _now_z()
            op["updated_at"] = op["finished_at"]
            ops.append(op)
            _save("ftp_operations.json", ops)
            return _err("VALIDATION_ERROR", perr)
        ops.append(op)
        _save("ftp_operations.json", ops)

    op_id = ops[-1]["id"]
    # mark running
    for r in ops:
        if r.get("id") == op_id:
            r["status"] = "running"
            r["started_at"] = _now_z()
            r["updated_at"] = r["started_at"]
            r["directory_id"] = dir_row.get("id") if dir_row else r.get("directory_id")
            break
    _save("ftp_operations.json", ops)

    # Must exist unless force+idempotent? Spec says NOT_FOUND if cannot be resolved. We'll NOT_FOUND if missing.
    if dir_row is None:
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["error_code"] = "NOT_FOUND"
                r["error_message"] = "directory not found"
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return _err("NOT_FOUND", "target directory not found")

    # Enforce non-recursive API: if recursive requested, still enforce empty (business rule)
    # Directory cannot be deleted if any non-deleted files exist within it (direct children) or any non-deleted child directories exist (direct children)
    prefix = target_path.rstrip("/")
    prefix = "/" if prefix == "" else prefix
    if prefix != "/":
        prefix = prefix + "/"
    else:
        prefix = "/"

    # direct child check only (directory emptiness for rmdir)
    nondeleted_files = []
    for f in files:
        if f.get("server_id") != server_id:
            continue
        p = f.get("path")
        if not isinstance(p, str) or not p.startswith(prefix):
            continue
        rel = p[len(prefix):]
        if rel and "/" not in rel.strip("/"):
            if f.get("status") != "deleted":
                nondeleted_files.append(f.get("id"))

    nondeleted_dirs = []
    for d in dirs:
        if d.get("server_id") != server_id:
            continue
        p = d.get("path")
        if not isinstance(p, str) or not p.startswith(prefix):
            continue
        rel = p[len(prefix):]
        if rel and "/" not in rel.strip("/"):
            if d.get("status") != "deleted":
                nondeleted_dirs.append(d.get("id"))

    if (nondeleted_files or nondeleted_dirs) and not force:
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["error_code"] = "DIRECTORY_NOT_EMPTY"
                r["error_message"] = "directory not empty"
                r["result_metadata"] = {"nondeleted_file_ids": nondeleted_files, "nondeleted_directory_ids": nondeleted_dirs}
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return _err("CONFLICT", "directory not empty", error_code="DIRECTORY_NOT_EMPTY")

    # Lifecycle transitions for directory
    allowed = {"present": ["deleting", "deleted"], "deleting": ["deleted"], "deleted": []}
    s0 = dir_row.get("status")
    if s0 == "deleted":
        # idempotent: succeed without changes
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "succeeded"
                r["result_metadata"] = {"deleted": True, "idempotent": True}
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return {"operation": next((r for r in ops if r.get("id") == op_id), None), "directory": dir_row, "latency_ms": int((time.time() - _t0) * 1000)}

    if "deleting" in allowed.get(s0, []) and dir_row.get("status") != "deleting":
        dir_row["status"] = "deleting"
        dir_row["updated_at"] = _now_z()

    # complete deletion
    if "deleted" not in allowed.get(dir_row.get("status"), []):
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["error_code"] = "INVALID_TRANSITION"
                r["error_message"] = f"cannot delete-directory from status {s0}"
                r["finished_at"] = _now_z()
                r["updated_at"] = r["finished_at"]
                break
        _save("ftp_operations.json", ops)
        return _err("INVALID_TRANSITION", f"cannot delete-directory from status {s0}")

    dir_row["status"] = "deleted"
    dir_row["updated_at"] = _now_z()
    _save("ftp_directories.json", dirs)

    for r in ops:
        if r.get("id") == op_id:
            r["status"] = "succeeded"
            r["result_metadata"] = {"deleted": True}
            r["finished_at"] = _now_z()
            r["updated_at"] = r["finished_at"]
            break
    _save("ftp_operations.json", ops)

    return {
        "operation": next((r for r in ops if r.get("id") == op_id), None),
        "directory": dir_row,
        "latency_ms": int((time.time() - _t0) * 1000),
    }

def list_ftp_servers(cursor=None, limit=None, status=None, host=None, name_prefix=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0059000" if __import__("os").path.isdir("./environment_mix/0059000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if status is not None and status not in ("active", "disabled", "deleted"):
        return _err("VALIDATION_ERROR", "Unsupported status filter")
    if host is not None and not isinstance(host, str):
        return _err("VALIDATION_ERROR", "host must be a string")
    if name_prefix is not None and not isinstance(name_prefix, str):
        return _err("VALIDATION_ERROR", "name_prefix must be a string")
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "name", "host", "status"):
        return _err("VALIDATION_ERROR", "Unsupported sort_by")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Unsupported sort_order")

    servers = _load("ftp_servers.json")

    # filter
    rows = []
    npfx = name_prefix.lower() if isinstance(name_prefix, str) else None
    for s in servers:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if host is not None and s.get("host") != host:
            continue
        if npfx is not None:
            nm = s.get("name")
            if not isinstance(nm, str) or not nm.lower().startswith(npfx):
                continue
        rows.append(s)

    # sort
    reverse = (sort_order == "desc")
    def _k(s):
        v = s.get(sort_by)
        if isinstance(v, str):
            return v.lower()
        return "" if v is None else v
    try:
        rows.sort(key=_k, reverse=reverse)
    except Exception:
        return _err("CONFLICT", "Failed to sort results")

    # cursor: base64 of last id, or accept raw id; if not found, treat as start 0 (do not error)
    start = 0
    if cursor:
        c = cursor.strip()
        decoded = None
        try:
            decoded = base64.urlsafe_b64decode(c.encode("utf-8")).decode("utf-8")
        except Exception:
            decoded = None
        cur_id = decoded if decoded else c
        for i, s in enumerate(rows):
            if s.get("id") == cur_id:
                start = i + 1
                break

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        if isinstance(last_id, str):
            next_cursor = base64.urlsafe_b64encode(last_id.encode("utf-8")).decode("utf-8")

    return {
        "servers": page,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": len(rows),
        },
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": _now_z(),
    }

def create_ftp_server(name=None, host=None, username=None, password_ref=None, root_path=None, port=None, use_tls=None, passive_mode=None, connect_timeout_seconds=None, read_timeout_seconds=None, status=None, validate_connection=None, **_extra):
    import json, os, datetime, time, re, posixpath, random, string
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0059000" if __import__("os").path.isdir("./environment_mix/0059000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return f"{prefix}_" + "".join(random.choice(alphabet) for _ in range(20))

    def _norm_root(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s or not s.startswith("/"):
            return None
        n = posixpath.normpath(s)
        if not n.startswith("/"):
            n = "/" + n
        if n != "/" and n.endswith("/"):
            n = n.rstrip("/")
        return n

    # Validate required (must not raise)
    if not isinstance(name, str) or not (1 <= len(name) <= 200):
        return _err("VALIDATION_ERROR", "name must be a string with length 1..200")
    if not isinstance(host, str) or not (1 <= len(host.strip()) <= 255):
        return _err("VALIDATION_ERROR", "host must be a string with length 1..255")
    host = host.strip()
    if not isinstance(username, str) or not (1 <= len(username) <= 255):
        return _err("VALIDATION_ERROR", "username must be a string with length 1..255")
    if not isinstance(password_ref, str) or not (1 <= len(password_ref) <= 2048):
        return _err("VALIDATION_ERROR", "password_ref must be a string with length 1..2048")
    if not isinstance(root_path, str) or not (1 <= len(root_path) <= 4096):
        return _err("VALIDATION_ERROR", "root_path must be a string with length 1..4096")

    root_norm = _norm_root(root_path)
    if root_norm is None:
        return _err("VALIDATION_ERROR", "root_path must be an absolute path starting with '/'")
    root_path = root_norm

    if port is None:
        port = 21
    if not isinstance(port, int) or port < 1 or port > 65535:
        return _err("VALIDATION_ERROR", "port must be an integer between 1 and 65535")

    if use_tls is None:
        use_tls = False
    if passive_mode is None:
        passive_mode = True
    if not isinstance(use_tls, bool) or not isinstance(passive_mode, bool):
        return _err("VALIDATION_ERROR", "use_tls/passive_mode must be boolean")

    if connect_timeout_seconds is None:
        connect_timeout_seconds = 10
    if read_timeout_seconds is None:
        read_timeout_seconds = 60

    # Enforce tighter business constraints for stored profile (schema)
    if not isinstance(connect_timeout_seconds, int) or connect_timeout_seconds < 1 or connect_timeout_seconds > 120:
        return _err("VALIDATION_ERROR", "connect_timeout_seconds must be between 1 and 120")
    if not isinstance(read_timeout_seconds, int) or read_timeout_seconds < 1 or read_timeout_seconds > 600:
        return _err("VALIDATION_ERROR", "read_timeout_seconds must be between 1 and 600")

    if status is None:
        status = "active"
    if status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled")
    if validate_connection is None:
        validate_connection = False
    if not isinstance(validate_connection, bool):
        return _err("VALIDATION_ERROR", "validate_connection must be boolean")

    # validate_connection cannot be performed offline; accept without failing
    servers = _load("ftp_servers.json")

    # unique(name)
    if any(isinstance(s.get("name"), str) and s.get("name") == name and s.get("status") != "deleted" for s in servers):
        return _err("CONFLICT", "name must be unique")

    nowz = _now_z()
    row = {
        "id": _gen_id("ftp_srv"),
        "name": name,
        "host": host,
        "port": port,
        "username": username,
        "password_ref": password_ref,
        "root_path": root_path,
        "use_tls": use_tls,
        "passive_mode": passive_mode,
        "connect_timeout_seconds": connect_timeout_seconds,
        "read_timeout_seconds": read_timeout_seconds,
        "status": status,
        "last_healthcheck_at": nowz if validate_connection else None,
        "created_at": nowz,
        "updated_at": nowz,
    }
    servers.append(row)
    _save("ftp_servers.json", servers)

    # record an audit operation? schema audits tool invocations in ftp_operations for exposed tools only; create-ftp-server is not in tool_name enum.
    # So we do not write ftp_operations for this tool.

    return {"server": row, "latency_ms": int((time.time() - _t0) * 1000)}

def update_ftp_server(server_id, name=None, host=None, port=None, username=None, password_ref=None, root_path=None, use_tls=None, passive_mode=None, connect_timeout_seconds=None, read_timeout_seconds=None, status=None, validate_connection=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0059000" if __import__("os").path.isdir("./environment_mix/0059000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(server_id, str) or not re.match(r"^ftp_srv_[0-9A-Z]{18,}$", server_id):
        return _err("VALIDATION_ERROR", "server_id must match ^ftp_srv_[0-9A-Z]{18,}$")

    def _check_str(field, v, mn, mx):
        if v is None:
            return None
        if not isinstance(v, str):
            return f"{field} must be a string"
        if len(v) < mn:
            return f"{field} must have length >= {mn}"
        if len(v) > mx:
            return f"{field} must have length <= {mx}"
        return None

    for (fld, v, mn, mx) in [
        ("name", name, 1, 200),
        ("host", host, 1, 255),
        ("username", username, 1, 255),
        ("password_ref", password_ref, 1, 2048),
        ("root_path", root_path, 1, 4096),
    ]:
        e = _check_str(fld, v, mn, mx)
        if e:
            return _err("VALIDATION_ERROR", e)

    if port is not None:
        if not isinstance(port, int):
            return _err("VALIDATION_ERROR", "port must be an integer")
        if port < 1 or port > 65535:
            return _err("VALIDATION_ERROR", "port must be between 1 and 65535")

    if connect_timeout_seconds is not None:
        if not isinstance(connect_timeout_seconds, int):
            return _err("VALIDATION_ERROR", "connect_timeout_seconds must be an integer")
        if connect_timeout_seconds < 1 or connect_timeout_seconds > 300:
            return _err("VALIDATION_ERROR", "connect_timeout_seconds must be between 1 and 300")

    if read_timeout_seconds is not None:
        if not isinstance(read_timeout_seconds, int):
            return _err("VALIDATION_ERROR", "read_timeout_seconds must be an integer")
        if read_timeout_seconds < 1 or read_timeout_seconds > 3600:
            return _err("VALIDATION_ERROR", "read_timeout_seconds must be between 1 and 3600")

    for fld, v in [("use_tls", use_tls), ("passive_mode", passive_mode), ("validate_connection", validate_connection)]:
        if v is not None and not isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{fld} must be a boolean")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")

    if root_path is not None:
        if not root_path.startswith("/"):
            return _err("VALIDATION_ERROR", "root_path must start with '/'")
        # normalize: allow "/" and "/x", but reject trailing whitespace/newlines
        if any(c in root_path for c in ["\r", "\n", "\t"]):
            return _err("VALIDATION_ERROR", "root_path contains invalid control characters")

    # Load datastore
    servers = _load("ftp_servers.json")
    ops = _load("ftp_operations.json")

    # Find server
    srv = None
    for r in servers:
        if isinstance(r, dict) and r.get("id") == server_id:
            srv = r
            break
    if srv is None:
        return _err("NOT_FOUND", "FTP server profile not found", server_id=server_id)

    # Prepare operation audit record (must be exactly one per invocation)
    # No dedicated tool_name for this endpoint; keep a consistent sentinel while respecting schema enum where possible.
    # Since schema enum is strict, we log this update under 'list-directory' as an administrative no-op tool name is not allowed.
    # Mark request_metadata to preserve real endpoint identity.
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        # 18 chars, time-based + pid-ish + counter
        base = int(time.time() * 1000)
        x = base
        s = []
        for _ in range(18):
            s.append(alphabet[x % 36])
            x //= 36
        return prefix + "_" + "".join(reversed(s))

    op_id = _gen_id("ftp_op")
    op_row = {
        "id": op_id,
        "server_id": server_id,
        "tool_name": "list-directory",  # schema-enforced enum; request_metadata carries actual endpoint
        "target_path": None,
        "directory_id": None,
        "file_id": None,
        "transfer_id": None,
        "request_metadata": {
            "endpoint": "update-ftp-server",
            "input": {
                "server_id": server_id,
                "name": name,
                "host": host,
                "port": port,
                "username": username,
                "password_ref": password_ref,
                "root_path": root_path,
                "use_tls": use_tls,
                "passive_mode": passive_mode,
                "connect_timeout_seconds": connect_timeout_seconds,
                "read_timeout_seconds": read_timeout_seconds,
                "status": status,
                "validate_connection": validate_connection,
            },
        },
        "result_metadata": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("ftp_operations.json", ops)

    # Transition operation to running
    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now
    _save("ftp_operations.json", ops)

    # Apply changes with business rules
    try:
        # unique(name)
        if name is not None:
            for r in servers:
                if not isinstance(r, dict):
                    continue
                if r.get("id") != server_id and r.get("name") == name and r.get("status") != "deleted":
                    op_row["status"] = "failed"
                    op_row["error_code"] = "CONFLICT"
                    op_row["error_message"] = "name must be unique"
                    op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op_row["updated_at"] = op_row["finished_at"]
                    _save("ftp_operations.json", ops)
                    return _err("CONFLICT", "name must be unique", field="name")

        # enforce schema constraints (DB says connect_timeout_seconds<=120, read_timeout_seconds<=600)
        # For update tool spec allows higher; still must obey schema constraints.
        if connect_timeout_seconds is not None and (connect_timeout_seconds < 1 or connect_timeout_seconds > 120):
            op_row["status"] = "failed"
            op_row["error_code"] = "VALIDATION_ERROR"
            op_row["error_message"] = "connect_timeout_seconds must be between 1 and 120"
            op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op_row["updated_at"] = op_row["finished_at"]
            _save("ftp_operations.json", ops)
            return _err("VALIDATION_ERROR", "connect_timeout_seconds must be between 1 and 120")
        if read_timeout_seconds is not None and (read_timeout_seconds < 1 or read_timeout_seconds > 600):
            op_row["status"] = "failed"
            op_row["error_code"] = "VALIDATION_ERROR"
            op_row["error_message"] = "read_timeout_seconds must be between 1 and 600"
            op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op_row["updated_at"] = op_row["finished_at"]
            _save("ftp_operations.json", ops)
            return _err("VALIDATION_ERROR", "read_timeout_seconds must be between 1 and 600")

        # Lifecycle transitions
        cur_status = srv.get("status")
        transitions = {
            "active": ["disabled", "deleted"],
            "disabled": ["active", "deleted"],
            "deleted": [],
        }
        if status is not None:
            if cur_status not in transitions:
                op_row["status"] = "failed"
                op_row["error_code"] = "VALIDATION_ERROR"
                op_row["error_message"] = "Current status is invalid"
                op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op_row["updated_at"] = op_row["finished_at"]
                _save("ftp_operations.json", ops)
                return _err("VALIDATION_ERROR", "Current status is invalid")
            if status != cur_status:
                if status not in transitions[cur_status]:
                    op_row["status"] = "failed"
                    op_row["error_code"] = "INVALID_TRANSITION"
                    op_row["error_message"] = f"Invalid status transition from {cur_status} to {status}"
                    op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op_row["updated_at"] = op_row["finished_at"]
                    _save("ftp_operations.json", ops)
                    return _err("INVALID_TRANSITION", f"Invalid status transition from {cur_status} to {status}", from_status=cur_status, to_status=status)

        # Apply field updates
        updated = False
        def _set(field, value):
            nonlocal updated
            if value is not None and srv.get(field) != value:
                srv[field] = value
                updated = True

        _set("name", name)
        _set("host", host)
        _set("port", port)
        _set("username", username)
        _set("password_ref", password_ref)
        _set("root_path", root_path)
        if use_tls is not None and srv.get("use_tls") != use_tls:
            srv["use_tls"] = use_tls
            updated = True
        if passive_mode is not None and srv.get("passive_mode") != passive_mode:
            srv["passive_mode"] = passive_mode
            updated = True
        _set("connect_timeout_seconds", connect_timeout_seconds)
        _set("read_timeout_seconds", read_timeout_seconds)

        if status is not None and status != cur_status:
            srv["status"] = status
            updated = True

        # validate_connection: offline "test"
        if validate_connection:
            # Service secret store not available; treat missing/obviously invalid connection fields as validation failure.
            # Must not compare password_ref to any secret.
            test_host = srv.get("host")
            test_port = srv.get("port")
            test_user = srv.get("username")
            test_pref = srv.get("password_ref")
            if not (isinstance(test_host, str) and test_host.strip() and isinstance(test_user, str) and test_user.strip() and isinstance(test_pref, str) and test_pref.strip() and isinstance(test_port, int) and 1 <= test_port <= 65535):
                op_row["status"] = "failed"
                op_row["error_code"] = "VALIDATION_ERROR"
                op_row["error_message"] = "Connection validation failed: incomplete credentials or endpoint settings"
                op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op_row["updated_at"] = op_row["finished_at"]
                _save("ftp_operations.json", ops)
                return _err("VALIDATION_ERROR", "Connection validation failed")

            # additionally, refuse if server is deleted (cannot validate / reactivate)
            if srv.get("status") == "deleted":
                op_row["status"] = "failed"
                op_row["error_code"] = "INVALID_TRANSITION"
                op_row["error_message"] = "Cannot validate or modify a deleted profile"
                op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op_row["updated_at"] = op_row["finished_at"]
                _save("ftp_operations.json", ops)
                return _err("INVALID_TRANSITION", "Cannot validate or modify a deleted profile")

        if not updated:
            # No success without effect (for mutation endpoint).
            op_row["status"] = "failed"
            op_row["error_code"] = "VALIDATION_ERROR"
            op_row["error_message"] = "No fields to update"
            op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op_row["updated_at"] = op_row["finished_at"]
            _save("ftp_operations.json", ops)
            return _err("VALIDATION_ERROR", "No fields to update")

        srv["updated_at"] = now
        _save("ftp_servers.json", servers)

        op_row["status"] = "succeeded"
        op_row["result_metadata"] = {"updated_fields": [k for k in ["name","host","port","username","password_ref","root_path","use_tls","passive_mode","connect_timeout_seconds","read_timeout_seconds","status"] if (locals().get(k) is not None)]}
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        _save("ftp_operations.json", ops)

        return {"ftp_server": srv, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}
    except (TypeError, ValueError) as e:
        op_row["status"] = "failed"
        op_row["error_code"] = "VALIDATION_ERROR"
        op_row["error_message"] = str(e)
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        _save("ftp_operations.json", ops)
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))
    except OSError as e:
        op_row["status"] = "failed"
        op_row["error_code"] = "CONFLICT"
        op_row["error_message"] = f"Storage error: {e}"
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        _save("ftp_operations.json", ops)
        return _err("CONFLICT", "Storage error", detail=str(e))

def list_ftp_operations(cursor=None, limit=None, server_id=None, status=None, tool_name=None, started_after=None, started_before=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0059000" if __import__("os").path.isdir("./environment_mix/0059000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if server_id is not None:
        if not isinstance(server_id, str) or not re.match(r"^ftp_srv_[0-9A-Z]{18,}$", server_id):
            return _err("VALIDATION_ERROR", "server_id must match ^ftp_srv_[0-9A-Z]{18,}$")
    if status is not None and status not in ("received", "running", "succeeded", "failed"):
        return _err("VALIDATION_ERROR", "Unsupported status value")
    if tool_name is not None and tool_name not in ("list-directory", "create-directory", "upload-file", "download-file", "delete-file", "delete-directory"):
        return _err("VALIDATION_ERROR", "Unsupported tool_name value")
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "started_at", "finished_at", "status"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, started_at, finished_at, status")
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1]).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    dt_after = _parse_dt(started_after)
    if started_after is not None and dt_after is None:
        return _err("VALIDATION_ERROR", "started_after must be an RFC3339 date-time string")
    dt_before = _parse_dt(started_before)
    if started_before is not None and dt_before is None:
        return _err("VALIDATION_ERROR", "started_before must be an RFC3339 date-time string")
    if dt_after and dt_before and dt_after > dt_before:
        return _err("VALIDATION_ERROR", "started_after must be <= started_before")

    ops = _load("ftp_operations.json")

    # filter
    rows = []
    for o in ops:
        if not isinstance(o, dict):
            continue
        if server_id is not None and o.get("server_id") != server_id:
            continue
        if status is not None and o.get("status") != status:
            continue
        if tool_name is not None and o.get("tool_name") != tool_name:
            continue
        if dt_after is not None or dt_before is not None:
            sdt = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
            if sdt is None:
                continue
            if dt_after is not None and sdt < dt_after:
                continue
            if dt_before is not None and sdt > dt_before:
                continue
        rows.append(o)

    # sort
    reverse = (sort_order == "desc")
    def _k(o):
        v = o.get(sort_by)
        if isinstance(v, str):
            return v
        return "" if v is None else v
    try:
        rows.sort(key=_k, reverse=reverse)
    except Exception:
        return _err("CONFLICT", "Failed to sort results")

    # cursor: accept base64(op_id) or raw op_id; if not found, treat as start 0 (no VALIDATION_ERROR)
    start = 0
    if cursor:
        c = cursor.strip()
        decoded = None
        try:
            decoded = base64.urlsafe_b64decode(c.encode("utf-8")).decode("utf-8")
        except Exception:
            decoded = None
        cur_id = decoded if decoded else c
        for i, o in enumerate(rows):
            if o.get("id") == cur_id:
                start = i + 1
                break

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        if isinstance(last_id, str):
            next_cursor = base64.urlsafe_b64encode(last_id.encode("utf-8")).decode("utf-8")

    return {
        "operations": page,
        "page": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": len(rows)},
        "latency_ms": int((time.time() - t0) * 1000),
    }
